$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot '..' 'ExportTerminalLogs.psm1') -Force
function Assert-Equal($Expected,$Actual,[string]$Message){if($Expected-ne$Actual){throw"$Message expected '$Expected', got '$Actual'"}};function New-Config($base){[pscustomobject]@{OutputDir=Join-Path $base 'logs';StatePath=Join-Path $base 'state.json';ReportPath=Join-Path $base 'run.json';InitialLookback='30d';Networks=@('Default');Target='';StripXml=$true}};function New-Record($id,$start,$end){[pscustomobject]@{logId=$id;sessionStart=$start;sessionEnd=$end;ipAddress='192.0.2.1';hostname='router';managedNetwork='Default'}};$records=@((New-Record 1 1000 2000),(New-Record 2 3000 4000));$searches=[Collections.Generic.List[string]]::new();$search={param($scheme,$query)$searches.Add("$scheme|$query");$records};$retrieve={param($record)[Text.Encoding]::UTF8.GetBytes("log $($record.logId)")};$base=Join-Path ([IO.Path]::GetTempPath()) "netld-term-$([guid]::NewGuid())";try{$config=New-Config $base;$first=Export-TerminalLogData $config $search $retrieve '2026-08-31T12:00:00Z';$second=Export-TerminalLogData $config $search $retrieve '2026-08-31T12:01:00Z';Assert-Equal 2 $first.archivedCount 'Initial count';Assert-Equal 0 $second.archivedCount 'Incremental count';Assert-Equal 4000 (Get-Content $config.StatePath -Raw|ConvertFrom-Json).lastSessionEnd 'Watermark';Assert-Equal "session,network|30d`nDefault" $searches[0] 'Initial search'}finally{Remove-Item $base -Recurse -Force -ErrorAction SilentlyContinue};Write-Host 'PowerShell terminal-log tests passed.'
